fn test_prime(candidate: u64) -> bool {
    // By definition we assume candidate > 1, but we guard against smaller inputs just in case.
    if candidate <= 1 {
        return false;
    }
    // Check divisibility from 2 up to sqrt(candidate). If any divisor is found, it's not prime.
    let mut f: u64 = 2;
    while f <= candidate / f {
        if candidate % f == 0 {
            return false;
        }
        f += 1;
    }
    true
}